import java.util.Scanner;

public class Main {
    static final int maxn = 512;
    static long n, m, M;
    static long[][] c = new long[maxn][maxn];
    static long[][] p = new long[maxn][maxn];

    static long g(int a, int b) {
        if (b == 0) return 1;
        return p[a + 1][b - 1] * p[2][b] % M * (a + 1 - b) % M;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        m = sc.nextLong();
        M = sc.nextLong();

        for (int i = 0; i < maxn; ++i) {
            c[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % M;
            }
        }

        for (int i = 0; i < maxn; ++i) {
            p[i][0] = 1;
            for (int j = 1; j < maxn; ++j) {
                p[i][j] = p[i][j - 1] * i % M;
            }
        }

        long total_sum = 0;
        for (int i = 2; i <= m; ++i) {
            for (int d = 1; d < i; ++d) {
                long intermediate = d * (d + 1) / 2 % M
                        * c[(int)(i - 1)][d] % M
                        * p[d + 1][d - 1] % M
                        * g((int)(n - d - 1), i - d) % M
                        * p[2][d] % M
                        * p[(int)(n + 1 - (d + 1))][(int)(m - i)] % M
                        * p[2][(int)(m - i)] % M;
                total_sum = (total_sum + 2 * intermediate) % M;
            }
        }
        System.out.println((total_sum * (n + 1 - m) % M));
        sc.close();
    }
}

